from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    out=[row[:] for row in grid]
    for dc in (-1,1):
        for r in range(h):
            for c in range(w):
                color=grid[r][c]
                if color==bg:
                    continue
                pr,pc=r-1,c-dc
                if 0<=pr<h and 0<=pc<w and grid[pr][pc]==color:
                    continue
                run=[]; rr,cc=r,c
                while 0<=rr<h and 0<=cc<w and grid[rr][cc]==color:
                    run.append((rr,cc)); rr+=1; cc+=dc
                if len(run)<2:
                    continue
                for (er,ec),(dr,dd) in ((run[0],(-1,-dc)),(run[-1],(1,dc))):
                    rr,cc=er+dr,ec+dd
                    while 0<=rr<h and 0<=cc<w and grid[rr][cc]==bg:
                        out[rr][cc]=color
                        rr+=dr; cc+=dd
    return out

